from __future__ import annotations

from typing import Annotated

from flext_core import m as core_m, s as core_s

from native_mro_consumer.foreign import NativeMroConsumerForeign


class NativeMroConsumerModelsState:
    """State owners used by actual native service compositions."""

    class ServiceOptions(core_m.ArbitraryTypesModel):
        """Declarative state must take precedence over the service default."""

        choice: Annotated[
            str,
            core_m.Field(validate_default=True, description="State field precedence."),
        ] = "state"

    class BehaviorOptions(ServiceOptions):
        """Operational behavior is not a model declaration."""

        def operate(self) -> str:
            """Return the selected operational state."""
            return self.choice

    class InheritedBehaviorOptions(BehaviorOptions):
        """Inherited behavior does not restore declarative ownership."""

    class PropertyOptions(ServiceOptions):
        """An unregistered operational property is not schema metadata."""

        @property
        def operation(self) -> str:
            """Operational state."""
            return self.choice

    class ForeignInheritedOptions(NativeMroConsumerForeign.State):
        """A local declaration cannot launder a foreign state ancestor."""

    class ValidatedOptions(ServiceOptions):
        """Registered Pydantic validation remains declarative."""

        @core_m.field_validator("choice")
        @classmethod
        def validate_choice(cls, value: str) -> str:
            """Validate the declared default."""
            return value.upper()

    class EmptyOptions(core_m.ArbitraryTypesModel):
        """An empty model establishes no field-state precedence."""

    class ServiceState(core_s[str]):
        """A service in the model family is still not declarative state."""

