from typing import Annotated, override

from flext_core import m as core_m, p, r, s as core_s

from native_mro_consumer.foreign import NativeMroConsumerForeign


class NativeMroConsumerRuntime:
    """Real classes with genuine native identity, never spoofed modules."""

    class Service(core_s[str]):
        """A genuine native service with a competing field default."""

        choice: Annotated[str, core_m.Field(description="Runtime default.")] = "runtime"

        @override
        def execute(self) -> p.Result[str]:
            """Return the selected state through the public operation."""
            return r[str].ok(self.choice)

    class ForeignService(NativeMroConsumerForeign.State, Service):
        """A native service that also inherits the foreign state owner."""

